    CreateLocationAzureBlobRequest.add_member(:authentication_type, Smithy::Schema::Shapes::ShapeRef.new(shape: AzureBlobAuthenticationType, location_name: 'AuthenticationType', traits: {"smithy.api#documentation" => "<p>Specifies the authentication method DataSync uses to access your Azure Blob\n      Storage. DataSync can access blob storage using a shared access signature\n      (SAS).</p>", "smithy.api#required" => {}}))
    CreateLocationAzureBlobRequest.add_member(:sas_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: AzureBlobSasConfiguration, location_name: 'SasConfiguration', traits: {"smithy.api#documentation" => "<p>Specifies the SAS configuration that allows DataSync to access your Azure Blob\n      Storage.</p>\n         <note>\n            <p>If you provide an authentication token using <code>SasConfiguration</code>, but do not\n        provide secret configuration details using <code>CmkSecretConfig</code> or\n          <code>CustomSecretConfig</code>, then DataSync stores the token using your\n          Amazon Web Services account's secrets manager secret.</p>\n         </note>"}))
    CreateLocationAzureBlobRequest.add_member(:blob_type, Smithy::Schema::Shapes::ShapeRef.new(shape: AzureBlobType, location_name: 'BlobType', traits: {"smithy.api#documentation" => "<p>Specifies the type of blob that you want your objects or files to be when transferring\n      them into Azure Blob Storage. Currently, DataSync only supports moving data into\n      Azure Blob Storage as block blobs. For more information on blob types, see the <a href=\"https://learn.microsoft.com/en-us/rest/api/storageservices/understanding-block-blobs--append-blobs--and-page-blobs\">Azure Blob Storage documentation</a>.</p>"}))
    CreateLocationAzureBlobRequest.add_member(:access_tier, Smithy::Schema::Shapes::ShapeRef.new(shape: AzureAccessTier, location_name: 'AccessTier', traits: {"smithy.api#documentation" => "<p>Specifies the access tier that you want your objects or files transferred into. This only\n      applies when using the location as a transfer destination. For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/creating-azure-blob-location.html#azure-blob-access-tiers\">Access tiers</a>.</p>"}))
