    CreateLocationEfsRequest.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: EfsSubdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>Specifies a mount path for your Amazon EFS file system. This is where DataSync reads or writes data on your file system (depending on if this is a source or\n      destination location).</p>\n         <p>By default, DataSync uses the root directory (or <a href=\"https://docs.aws.amazon.com/efs/latest/ug/efs-access-points.html\">access point</a> if you provide one by using\n        <code>AccessPointArn</code>). You can also include subdirectories using forward slashes (for\n      example, <code>/path/to/folder</code>).</p>"}))
