    CreateLocationEfsRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: InputTagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Specifies the key-value pair that represents a tag that you want to add to the\n      resource. The value can be an empty string. This value helps you manage, filter, and search\n      for your resources. We recommend that you create a name tag for your location.</p>"}))
