    CreateLocationEfsRequest.add_member(:in_transit_encryption, Smithy::Schema::Shapes::ShapeRef.new(shape: EfsInTransitEncryption, location_name: 'InTransitEncryption', traits: {"smithy.api#documentation" => "<p>Specifies whether you want DataSync to use Transport Layer Security (TLS) 1.2\n      encryption when it transfers data to or from your Amazon EFS file system.</p>\n         <p>If you specify an access point using <code>AccessPointArn</code> or an IAM\n      role using <code>FileSystemAccessRoleArn</code>, you must set this parameter to\n        <code>TLS1_2</code>.</p>"}))
