    CreateLocationFsxWindowsRequest.add_member(:security_group_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: Ec2SecurityGroupArnList, location_name: 'SecurityGroupArns', traits: {"smithy.api#documentation" => "<p>Specifies the ARNs of the Amazon EC2 security groups that provide access to your\n      file system's preferred subnet.</p>\n         <p>The security groups that you specify must be able to communicate with your file system's\n      security groups. For information about configuring security groups for file system access, see\n      the <a href=\"https://docs.aws.amazon.com/fsx/latest/WindowsGuide/limit-access-security-groups.html\">\n               <i>Amazon FSx for Windows File Server User Guide</i>\n            </a>.</p>\n         <note>\n            <p>If you choose a security group that doesn't allow connections from within itself, do one\n        of the following:</p>\n            <ul>\n               <li>\n                  <p>Configure the security group to allow it to communicate within itself.</p>\n               </li>\n               <li>\n                  <p>Choose a different security group that can communicate with the mount target's\n            security group.</p>\n               </li>\n            </ul>\n         </note>", "smithy.api#required" => {}}))
    CreateLocationFsxWindowsRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: InputTagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Specifies labels that help you categorize, filter, and search for your Amazon Web Services\n      resources. We recommend creating at least a name tag for your location.</p>"}))
    CreateLocationFsxWindowsRequest.add_member(:user, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbUser, location_name: 'User', traits: {"smithy.api#documentation" => "<p>Specifies the user with the permissions to mount and access the files, folders, and file\n      metadata in your FSx for Windows File Server file system.</p>\n         <p>For information about choosing a user with the right level of access for your transfer,\n      see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/create-fsx-location.html#create-fsx-windows-location-permissions\">required permissions</a> for FSx for Windows File Server locations.</p>", "smithy.api#required" => {}}))
