    CreateLocationHdfsRequest.add_member(:name_nodes, Smithy::Schema::Shapes::ShapeRef.new(shape: HdfsNameNodeList, location_name: 'NameNodes', traits: {"smithy.api#documentation" => "<p>The NameNode that manages the HDFS namespace. The NameNode performs operations such as\n      opening, closing, and renaming files and directories. The NameNode contains the information to\n      map blocks of data to the DataNodes. You can use only one NameNode.</p>", "smithy.api#required" => {}}))
