    CreateLocationHdfsRequest.add_member(:kerberos_principal, Smithy::Schema::Shapes::ShapeRef.new(shape: KerberosPrincipal, location_name: 'KerberosPrincipal', traits: {"smithy.api#documentation" => "<p>The Kerberos principal with access to the files and folders on the HDFS cluster. </p>\n         <note>\n            <p>If <code>KERBEROS</code> is specified for <code>AuthenticationType</code>, this\n        parameter is required.</p>\n         </note>"}))
    CreateLocationHdfsRequest.add_member(:kerberos_keytab, Smithy::Schema::Shapes::ShapeRef.new(shape: KerberosKeytabFile, location_name: 'KerberosKeytab', traits: {"smithy.api#documentation" => "<p>The Kerberos key table (keytab) that contains mappings between the defined Kerberos\n      principal and the encrypted keys. You can load the keytab from a file by providing the file's\n      address.</p>\n         <note>\n            <p>If <code>KERBEROS</code> is specified for <code>AuthenticationType</code>, this\n        parameter is required. </p>\n         </note>"}))
    CreateLocationHdfsRequest.add_member(:kerberos_krb5_conf, Smithy::Schema::Shapes::ShapeRef.new(shape: KerberosKrb5ConfFile, location_name: 'KerberosKrb5Conf', traits: {"smithy.api#documentation" => "<p>The <code>krb5.conf</code> file that contains the Kerberos configuration information. You\n      can load the <code>krb5.conf</code> file by providing the file's address. If you're using the\n        CLI, it performs the base64 encoding for you. Otherwise, provide the\n      base64-encoded text. </p>\n         <note>\n            <p>If <code>KERBEROS</code> is specified for <code>AuthenticationType</code>, this\n        parameter is required.</p>\n         </note>"}))
