    CreateLocationNfsRequest.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: NfsSubdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>Specifies the export path in your NFS file server that you want DataSync to\n      mount.</p>\n         <p>This path (or a subdirectory of the path) is where DataSync transfers data to\n      or from. For information on configuring an export for DataSync, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/create-nfs-location.html#accessing-nfs\">Accessing NFS file servers</a>.</p>", "smithy.api#required" => {}}))
    CreateLocationNfsRequest.add_member(:server_hostname, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerHostname, location_name: 'ServerHostname', traits: {"smithy.api#documentation" => "<p>Specifies the DNS name or IP address (IPv4 or IPv6) of the NFS file server that your DataSync agent connects to.</p>", "smithy.api#required" => {}}))
    CreateLocationNfsRequest.add_member(:on_prem_config, Smithy::Schema::Shapes::ShapeRef.new(shape: OnPremConfig, location_name: 'OnPremConfig', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Resource Name (ARN) of the DataSync agent that can\n      connect to your NFS file server.</p>\n         <p>You can specify more than one agent. For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/do-i-need-datasync-agent.html#multiple-agents\">Using multiple DataSync agents</a>.</p>", "smithy.api#required" => {}}))
    CreateLocationNfsRequest.add_member(:mount_options, Smithy::Schema::Shapes::ShapeRef.new(shape: NfsMountOptions, location_name: 'MountOptions', traits: {"smithy.api#documentation" => "<p>Specifies the options that DataSync can use to mount your NFS file\n      server.</p>"}))
