    CreateLocationObjectStorageRequest.add_member(:server_port, Smithy::Schema::Shapes::ShapeRef.new(shape: ObjectStorageServerPort, location_name: 'ServerPort', traits: {"smithy.api#documentation" => "<p>Specifies the port that your object storage server accepts inbound network traffic on (for\n      example, port 443).</p>"}))
    CreateLocationObjectStorageRequest.add_member(:server_protocol, Smithy::Schema::Shapes::ShapeRef.new(shape: ObjectStorageServerProtocol, location_name: 'ServerProtocol', traits: {"smithy.api#documentation" => "<p>Specifies the protocol that your object storage server uses to communicate. If not specified, the default\n      value is <code>HTTPS</code>.</p>"}))
    CreateLocationObjectStorageRequest.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: S3Subdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>Specifies the object prefix for your object storage server. If this is a source location,\n        DataSync only copies objects with this prefix. If this is a destination location,\n        DataSync writes all objects with this prefix. </p>"}))
    CreateLocationObjectStorageRequest.add_member(:bucket_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ObjectStorageBucketName, location_name: 'BucketName', traits: {"smithy.api#documentation" => "<p>Specifies the name of the object storage bucket involved in the transfer.</p>", "smithy.api#required" => {}}))
    CreateLocationObjectStorageRequest.add_member(:access_key, Smithy::Schema::Shapes::ShapeRef.new(shape: ObjectStorageAccessKey, location_name: 'AccessKey', traits: {"smithy.api#documentation" => "<p>Specifies the access key (for example, a user name) if credentials are required to\n      authenticate with the object storage server.</p>"}))
    CreateLocationObjectStorageRequest.add_member(:secret_key, Smithy::Schema::Shapes::ShapeRef.new(shape: ObjectStorageSecretKey, location_name: 'SecretKey', traits: {"smithy.api#documentation" => "<p>Specifies the secret key (for example, a password) if credentials are required to\n      authenticate with the object storage server.</p>\n         <note>\n            <p>If you provide a secret using <code>SecretKey</code>, but do not provide secret\n        configuration details using <code>CmkSecretConfig</code> or <code>CustomSecretConfig</code>,\n        then DataSync stores the token using your Amazon Web Services account's Secrets Manager secret.</p>\n         </note>"}))
    CreateLocationObjectStorageRequest.add_member(:agent_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: AgentArnList, location_name: 'AgentArns', traits: {"smithy.api#documentation" => "<p>(Optional) Specifies the Amazon Resource Names (ARNs) of the DataSync agents\n      that can connect with your object storage system. If you are setting up an agentless\n      cross-cloud transfer, you do not need to specify a value for this parameter.</p>\n         <note>\n            <p>Make sure you configure this parameter correctly when you first create your storage\n        location. You cannot add or remove agents from a storage location after you create\n        it.</p>\n         </note>"}))
    CreateLocationObjectStorageRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: InputTagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Specifies the key-value pair that represents a tag that you want to add to the resource.\n      Tags can help you manage, filter, and search for your resources. We recommend creating a name\n      tag for your location.</p>"}))
    CreateLocationObjectStorageRequest.add_member(:server_certificate, Smithy::Schema::Shapes::ShapeRef.new(shape: ObjectStorageCertificate, location_name: 'ServerCertificate', traits: {"smithy.api#documentation" => "<p>Specifies a certificate chain for DataSync to authenticate with your object\n      storage system if the system uses a private or self-signed certificate authority (CA). You\n      must specify a single <code>.pem</code> file with a full certificate chain (for example,\n        <code>file:///home/user/.ssh/object_storage_certificates.pem</code>).</p>\n         <p>The certificate chain might include:</p>\n         <ul>\n            <li>\n               <p>The object storage system's certificate</p>\n            </li>\n            <li>\n               <p>All intermediate certificates (if there are any)</p>\n            </li>\n            <li>\n               <p>The root certificate of the signing CA</p>\n            </li>\n         </ul>\n         <p>You can concatenate your certificates into a <code>.pem</code> file (which can be up to\n      32768 bytes before base64 encoding). The following example <code>cat</code> command creates an\n        <code>object_storage_certificates.pem</code> file that includes three certificates:</p>\n         <p>\n            <code>cat object_server_certificate.pem intermediate_certificate.pem\n        ca_root_certificate.pem > object_storage_certificates.pem</code>\n         </p>\n         <p>To use this parameter, configure <code>ServerProtocol</code> to <code>HTTPS</code>.</p>"}))
    CreateLocationObjectStorageRequest.add_member(:cmk_secret_config, Smithy::Schema::Shapes::ShapeRef.new(shape: CmkSecretConfig, location_name: 'CmkSecretConfig', traits: {"smithy.api#documentation" => "<p>Specifies configuration information for a DataSync-managed secret, which\n      includes the <code>SecretKey</code> that DataSync uses to access a specific object\n      storage location, with a customer-managed KMS key.</p>\n         <p>When you include this paramater as part of a <code>CreateLocationObjectStorage</code>\n      request, you provide only the KMS key ARN. DataSync uses this KMS key together with the value you specify for the <code>SecretKey</code> parameter\n      to create a DataSync-managed secret to store the location access credentials.</p>\n         <p>Make sure the DataSync has permission to access the KMS key that\n      you specify.</p>\n         <note>\n            <p>You can use either <code>CmkSecretConfig</code> (with <code>SecretKey</code>) or\n          <code>CustomSecretConfig</code> (without <code>SecretKey</code>) to provide credentials\n        for a <code>CreateLocationObjectStorage</code> request. Do not provide both parameters for\n        the same request.</p>\n         </note>"}))
    CreateLocationObjectStorageRequest.add_member(:custom_secret_config, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomSecretConfig, location_name: 'CustomSecretConfig', traits: {"smithy.api#documentation" => "<p>Specifies configuration information for a customer-managed Secrets Manager secret where\n      the secret key for a specific object storage location is stored in plain text. This\n      configuration includes the secret ARN, and the ARN for an IAM role that\n      provides access to the secret.</p>\n         <note>\n            <p>You can use either <code>CmkSecretConfig</code> (with <code>SecretKey</code>) or\n          <code>CustomSecretConfig</code> (without <code>SecretKey</code>) to provide credentials\n        for a <code>CreateLocationObjectStorage</code> request. Do not provide both parameters for\n        the same request.</p>\n         </note>"}))
    CreateLocationObjectStorageRequest.type = Types::CreateLocationObjectStorageRequest
    CreateLocationObjectStorageResponse.add_member(:location_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationArn, location_name: 'LocationArn', traits: {"smithy.api#documentation" => "<p>Specifies the ARN of the object storage system location that you create.</p>"}))
    CreateLocationObjectStorageResponse.type = Types::CreateLocationObjectStorageResponse
    CreateLocationS3Request.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: S3Subdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>Specifies a prefix in the S3 bucket that DataSync reads from or writes to\n      (depending on whether the bucket is a source or destination location).</p>\n         <note>\n            <p>DataSync can't transfer objects with a prefix that begins with a slash (<code>/</code>)\n        or includes <code>//</code>, <code>/./</code>, or <code>/../</code> patterns. For\n        example:</p>\n            <ul>\n               <li>\n                  <p>\n                     <code>/photos</code>\n                  </p>\n               </li>\n               <li>\n                  <p>\n                     <code>photos//2006/January</code>\n                  </p>\n               </li>\n               <li>\n                  <p>\n                     <code>photos/./2006/February</code>\n                  </p>\n               </li>\n               <li>\n                  <p>\n                     <code>photos/../2006/March</code>\n                  </p>\n               </li>\n            </ul>\n         </note>"}))
    CreateLocationS3Request.add_member(:s3_bucket_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: S3BucketArn, location_name: 'S3BucketArn', traits: {"smithy.api#documentation" => "<p>Specifies the ARN of the S3 bucket that you want to use as a location. (When creating\n      your DataSync task later, you specify whether this location is a transfer source or\n      destination.) </p>\n         <p>If your S3 bucket is located on an Outposts resource, you must specify an\n        Amazon S3 access point. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonS3/latest/userguide/access-points.html\">Managing data access\n        with Amazon S3 access points</a> in the <i>Amazon S3 User\n        Guide</i>.</p>", "smithy.api#required" => {}}))
    CreateLocationS3Request.add_member(:s3_storage_class, Smithy::Schema::Shapes::ShapeRef.new(shape: S3StorageClass, location_name: 'S3StorageClass', traits: {"smithy.api#documentation" => "<p>Specifies the storage class that you want your objects to use when Amazon S3 is a\n      transfer destination.</p>\n         <p>For buckets in Amazon Web Services Regions, the storage class defaults to\n        <code>STANDARD</code>. For buckets on Outposts, the storage class defaults to\n        <code>OUTPOSTS</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/create-s3-location.html#using-storage-classes\">Storage class\n        considerations with Amazon S3 transfers</a>.</p>"}))
    CreateLocationS3Request.add_member(:s3_config, Smithy::Schema::Shapes::ShapeRef.new(shape: S3Config, location_name: 'S3Config', traits: {"smithy.api#required" => {}}))
    CreateLocationS3Request.add_member(:agent_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: AgentArnList, location_name: 'AgentArns', traits: {"smithy.api#documentation" => "<p>(Amazon S3 on Outposts only) Specifies the Amazon Resource Name (ARN) of the\n        DataSync agent on your Outpost.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/deploy-agents.html#outposts-agent\">Deploy your DataSync agent on Outposts</a>.</p>"}))
    CreateLocationS3Request.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: InputTagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Specifies labels that help you categorize, filter, and search for your Amazon Web Services resources. We recommend creating at least a name tag for your transfer location.</p>"}))
    CreateLocationS3Request.type = Types::CreateLocationS3Request
    CreateLocationS3Response.add_member(:location_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationArn, location_name: 'LocationArn', traits: {"smithy.api#documentation" => "<p>The ARN of the S3 location that you created.</p>"}))
    CreateLocationS3Response.type = Types::CreateLocationS3Response
    CreateLocationSmbRequest.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbSubdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>Specifies the name of the share exported by your SMB file server where DataSync\n      will read or write data. You can include a subdirectory in the share path (for example,\n        <code>/path/to/subdirectory</code>). Make sure that other SMB clients in your network can\n      also mount this path.</p>\n         <p>To copy all data in the subdirectory, DataSync must be able to mount the SMB\n      share and access all of its data. For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/create-smb-location.html#configuring-smb-permissions\">Providing DataSync access to SMB file servers</a>.</p>", "smithy.api#required" => {}}))
    CreateLocationSmbRequest.add_member(:server_hostname, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerHostname, location_name: 'ServerHostname', traits: {"smithy.api#documentation" => "<p>Specifies the domain name or IP address (IPv4 or IPv6) of the SMB file server that your DataSync agent connects to.</p>\n         <note>\n            <p>If you're using Kerberos authentication, you must specify a domain name.</p>\n         </note>", "smithy.api#required" => {}}))
    CreateLocationSmbRequest.add_member(:user, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbUser, location_name: 'User', traits: {"smithy.api#documentation" => "<p>Specifies the user that can mount and access the files, folders, and file metadata in your\n      SMB file server. This parameter applies only if <code>AuthenticationType</code> is set to\n        <code>NTLM</code>.</p>\n         <p>For information about choosing a user with the right level of access for your transfer,\n      see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/create-smb-location.html#configuring-smb-permissions\">Providing DataSync access to SMB file servers</a>.</p>"}))
    CreateLocationSmbRequest.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbDomain, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>Specifies the Windows domain name that your SMB file server belongs to. This parameter\n      applies only if <code>AuthenticationType</code> is set to <code>NTLM</code>.</p>\n         <p>If you have multiple domains in your environment, configuring this parameter makes sure\n      that DataSync connects to the right file server.</p>"}))
    CreateLocationSmbRequest.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbPassword, location_name: 'Password', traits: {"smithy.api#documentation" => "<p>Specifies the password of the user who can mount your SMB file server and has permission\n      to access the files and folders involved in your transfer. This parameter applies only if\n        <code>AuthenticationType</code> is set to <code>NTLM</code>.</p>"}))
    CreateLocationSmbRequest.add_member(:agent_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: AgentArnList, location_name: 'AgentArns', traits: {"smithy.api#documentation" => "<p>Specifies the DataSync agent (or agents) that can connect to your SMB file\n      server. You specify an agent by using its Amazon Resource Name (ARN).</p>", "smithy.api#required" => {}}))
    CreateLocationSmbRequest.add_member(:mount_options, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbMountOptions, location_name: 'MountOptions', traits: {"smithy.api#documentation" => "<p>Specifies the version of the SMB protocol that DataSync uses to access your SMB\n      file server.</p>"}))
    CreateLocationSmbRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: InputTagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Specifies labels that help you categorize, filter, and search for your Amazon Web Services\n      resources. We recommend creating at least a name tag for your location.</p>"}))
    CreateLocationSmbRequest.add_member(:authentication_type, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbAuthenticationType, location_name: 'AuthenticationType', traits: {"smithy.api#documentation" => "<p>Specifies the authentication protocol that DataSync uses to connect to your SMB\n      file server. DataSync supports <code>NTLM</code> (default) and <code>KERBEROS</code>\n      authentication.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/create-smb-location.html#configuring-smb-permissions\">Providing DataSync access to SMB file servers</a>.</p>"}))
    CreateLocationSmbRequest.add_member(:dns_ip_addresses, Smithy::Schema::Shapes::ShapeRef.new(shape: DnsIpList, location_name: 'DnsIpAddresses', traits: {"smithy.api#documentation" => "<p>Specifies the IPv4 or IPv6 addresses for the DNS servers that your SMB file server belongs to.\n      This parameter applies only if <code>AuthenticationType</code> is set to\n      <code>KERBEROS</code>.</p>\n         <p>If you have multiple domains in your environment, configuring this parameter makes sure\n      that DataSync connects to the right SMB file server.</p>"}))
    CreateLocationSmbRequest.add_member(:kerberos_principal, Smithy::Schema::Shapes::ShapeRef.new(shape: KerberosPrincipal, location_name: 'KerberosPrincipal', traits: {"smithy.api#documentation" => "<p>Specifies a Kerberos principal, which is an identity in your Kerberos realm that has\n      permission to access the files, folders, and file metadata in your SMB file server.</p>\n         <p>A Kerberos principal might look like <code>HOST/kerberosuser@MYDOMAIN.ORG</code>.</p>\n         <p>Principal names are case sensitive. Your DataSync task execution will fail if\n      the principal that you specify for this parameter doesn’t exactly match the principal that you\n      use to create the keytab file.</p>"}))
    CreateLocationSmbRequest.add_member(:kerberos_keytab, Smithy::Schema::Shapes::ShapeRef.new(shape: KerberosKeytabFile, location_name: 'KerberosKeytab', traits: {"smithy.api#documentation" => "<p>Specifies your Kerberos key table (keytab) file, which includes mappings between your\n      Kerberos principal and encryption keys.</p>\n         <p>To avoid task execution errors, make sure that the Kerberos principal that you use to\n      create the keytab file matches exactly what you specify for <code>KerberosPrincipal</code>.\n    </p>"}))
    CreateLocationSmbRequest.add_member(:kerberos_krb5_conf, Smithy::Schema::Shapes::ShapeRef.new(shape: KerberosKrb5ConfFile, location_name: 'KerberosKrb5Conf', traits: {"smithy.api#documentation" => "<p>Specifies a Kerberos configuration file (<code>krb5.conf</code>) that defines your\n      Kerberos realm configuration.</p>\n         <p>The file must be base64 encoded. If you're using the CLI, the encoding is\n      done for you.</p>"}))
    CreateLocationSmbRequest.type = Types::CreateLocationSmbRequest
    CreateLocationSmbResponse.add_member(:location_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationArn, location_name: 'LocationArn', traits: {"smithy.api#documentation" => "<p>The ARN of the SMB location that you created.</p>"}))
    CreateLocationSmbResponse.type = Types::CreateLocationSmbResponse
    CreateTaskRequest.add_member(:source_location_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationArn, location_name: 'SourceLocationArn', traits: {"smithy.api#documentation" => "<p>Specifies the ARN of your transfer's source location.</p>", "smithy.api#required" => {}}))
    CreateTaskRequest.add_member(:destination_location_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationArn, location_name: 'DestinationLocationArn', traits: {"smithy.api#documentation" => "<p>Specifies the ARN of your transfer's destination location. </p>", "smithy.api#required" => {}}))
    CreateTaskRequest.add_member(:cloud_watch_log_group_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LogGroupArn, location_name: 'CloudWatchLogGroupArn', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Resource Name (ARN) of an Amazon CloudWatch log group for\n      monitoring your task.</p>\n         <p>For Enhanced mode tasks, you don't need to specify anything. DataSync\n      automatically sends logs to a CloudWatch log group named\n      <code>/aws/datasync</code>.</p>"}))
    CreateTaskRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: TagValue, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>Specifies the name of your task.</p>"}))
    CreateTaskRequest.add_member(:options, Smithy::Schema::Shapes::ShapeRef.new(shape: Options, location_name: 'Options', traits: {"smithy.api#documentation" => "<p>Specifies your task's settings, such as preserving file metadata, verifying data\n      integrity, among other options.</p>"}))
    CreateTaskRequest.add_member(:excludes, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterList, location_name: 'Excludes', traits: {"smithy.api#documentation" => "<p>Specifies exclude filters that define the files, objects, and folders in your source\n      location that you don't want DataSync to transfer. For more information and\n      examples, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/filtering.html\">Specifying what DataSync transfers by using filters</a>.</p>"}))
    CreateTaskRequest.add_member(:schedule, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskSchedule, location_name: 'Schedule', traits: {"smithy.api#documentation" => "<p>Specifies a schedule for when you want your task to run. For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/task-scheduling.html\">Scheduling your\n        task</a>.</p>"}))
    CreateTaskRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: InputTagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Specifies the tags that you want to apply to your task.</p>\n         <p>\n            <i>Tags</i> are key-value pairs that help you manage, filter, and search\n      for your DataSync resources.</p>"}))
    CreateTaskRequest.add_member(:includes, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterList, location_name: 'Includes', traits: {"smithy.api#documentation" => "<p>Specifies include filters that define the files, objects, and folders in your source\n      location that you want DataSync to transfer. For more information and examples, see\n        <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/filtering.html\">Specifying what\n          DataSync transfers by using filters</a>.</p>"}))
    CreateTaskRequest.add_member(:manifest_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ManifestConfig, location_name: 'ManifestConfig', traits: {"smithy.api#documentation" => "<p>Configures a manifest, which is a list of files or objects that you want DataSync to transfer. For more information and configuration examples, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/transferring-with-manifest.html\">Specifying what DataSync transfers by using a manifest</a>.</p>\n         <p>When using this parameter, your caller identity (the role that you're using DataSync with) must have the <code>iam:PassRole</code> permission. The <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/security-iam-awsmanpol.html#security-iam-awsmanpol-awsdatasyncfullaccess\">AWSDataSyncFullAccess</a> policy includes this permission.</p>"}))
    CreateTaskRequest.add_member(:task_report_config, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskReportConfig, location_name: 'TaskReportConfig', traits: {"smithy.api#documentation" => "<p>Specifies how you want to configure a task report, which provides detailed information\n      about your DataSync transfer. For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/task-reports.html\">Monitoring your DataSync\n        transfers with task reports</a>.</p>\n         <p>When using this parameter, your caller identity (the role that you're using DataSync with) must have the <code>iam:PassRole</code> permission. The <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/security-iam-awsmanpol.html#security-iam-awsmanpol-awsdatasyncfullaccess\">AWSDataSyncFullAccess</a> policy includes this permission.</p>"}))
    CreateTaskRequest.add_member(:task_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskMode, location_name: 'TaskMode', traits: {"smithy.api#documentation" => "<p>Specifies one of the following task modes for your data transfer:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ENHANCED</code> - Transfer virtually unlimited numbers of objects with higher\n          performance than Basic mode. Enhanced mode tasks optimize the data transfer process by\n          listing, preparing, transferring, and verifying data in parallel. Enhanced mode is\n          currently available for transfers between Amazon S3 locations, transfers between\n          Azure Blob and Amazon S3 without an agent, and transfers between other clouds and\n            Amazon S3 without an agent.</p>\n               <note>\n                  <p>To create an Enhanced mode task, the IAM role that you use to call\n            the <code>CreateTask</code> operation must have the\n              <code>iam:CreateServiceLinkedRole</code> permission.</p>\n               </note>\n            </li>\n            <li>\n               <p>\n                  <code>BASIC</code> (default) - Transfer files or objects between Amazon Web Services\n          storage and all other supported DataSync locations. Basic mode tasks are subject\n          to <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/datasync-limits.html\">quotas</a> on the number of files, objects, and directories in a dataset. Basic\n          mode sequentially prepares, transfers, and verifies data, making it slower than Enhanced\n          mode for most workloads.</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/choosing-task-mode.html#task-mode-differences\">Understanding\n        task mode differences</a>.</p>"}))
    CreateTaskRequest.type = Types::CreateTaskRequest
    CreateTaskResponse.add_member(:task_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskArn, location_name: 'TaskArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the task.</p>"}))
    CreateTaskResponse.type = Types::CreateTaskResponse
    CustomSecretConfig.add_member(:secret_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretArn, location_name: 'SecretArn', traits: {"smithy.api#documentation" => "<p>Specifies the ARN for an Secrets Manager secret.</p>"}))
    CustomSecretConfig.add_member(:secret_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IamRoleArnOrEmptyString, location_name: 'SecretAccessRoleArn', traits: {"smithy.api#documentation" => "<p>Specifies the ARN for the Identity and Access Management role that DataSync uses to\n      access the secret specified for <code>SecretArn</code>.</p>"}))
    CustomSecretConfig.type = Types::CustomSecretConfig
