    DescribeAgentRequest.type = Types::DescribeAgentRequest
    DescribeAgentResponse.add_member(:agent_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: AgentArn, location_name: 'AgentArn', traits: {"smithy.api#documentation" => "<p>The ARN of the agent.</p>"}))
    DescribeAgentResponse.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: TagValue, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the agent.</p>"}))
    DescribeAgentResponse.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: AgentStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the agent.</p>\n         <ul>\n            <li>\n               <p>If the status is <code>ONLINE</code>, the agent is configured properly and ready to\n          use.</p>\n            </li>\n            <li>\n               <p>If the status is <code>OFFLINE</code>, the agent has been out of contact with\n            DataSync for five minutes or longer. This can happen for a few reasons. For\n          more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/troubleshooting-datasync-agents.html#troubleshoot-agent-offline\">What do I do if my agent is offline?</a>\n               </p>\n            </li>\n         </ul>"}))
    DescribeAgentResponse.add_member(:last_connection_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Time, location_name: 'LastConnectionTime', traits: {"smithy.api#documentation" => "<p>The last time that the agent was communicating with the DataSync\n      service.</p>"}))
    DescribeAgentResponse.add_member(:creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Time, location_name: 'CreationTime', traits: {"smithy.api#documentation" => "<p>The time that the agent was <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/activate-agent.html\">activated</a>.</p>"}))
    DescribeAgentResponse.add_member(:endpoint_type, Smithy::Schema::Shapes::ShapeRef.new(shape: EndpointType, location_name: 'EndpointType', traits: {"smithy.api#documentation" => "<p>The type of <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/choose-service-endpoint.html\">service endpoint</a> that your agent is connected to.</p>"}))
    DescribeAgentResponse.add_member(:private_link_config, Smithy::Schema::Shapes::ShapeRef.new(shape: PrivateLinkConfig, location_name: 'PrivateLinkConfig', traits: {"smithy.api#documentation" => "<p>The network configuration that the agent uses when connecting to a <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/choose-service-endpoint.html#choose-service-endpoint-vpc\">VPC\n        service endpoint</a>.</p>"}))
    DescribeAgentResponse.add_member(:platform, Smithy::Schema::Shapes::ShapeRef.new(shape: Platform, location_name: 'Platform', traits: {"smithy.api#documentation" => "<p>The platform-related details about the agent, such as the version number.</p>"}))
    DescribeAgentResponse.type = Types::DescribeAgentResponse
    DescribeLocationAzureBlobRequest.add_member(:location_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationArn, location_name: 'LocationArn', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Resource Name (ARN) of your Azure Blob Storage transfer\n      location.</p>", "smithy.api#required" => {}}))
    DescribeLocationAzureBlobRequest.type = Types::DescribeLocationAzureBlobRequest
    DescribeLocationAzureBlobResponse.add_member(:location_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationArn, location_name: 'LocationArn', traits: {"smithy.api#documentation" => "<p>The ARN of your Azure Blob Storage transfer location.</p>"}))
    DescribeLocationAzureBlobResponse.add_member(:location_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationUri, location_name: 'LocationUri', traits: {"smithy.api#documentation" => "<p>The URL of the Azure Blob Storage container involved in your transfer.</p>"}))
    DescribeLocationAzureBlobResponse.add_member(:authentication_type, Smithy::Schema::Shapes::ShapeRef.new(shape: AzureBlobAuthenticationType, location_name: 'AuthenticationType', traits: {"smithy.api#documentation" => "<p>The authentication method DataSync uses to access your Azure Blob Storage.\n        DataSync can access blob storage using a shared access signature (SAS).</p>"}))
    DescribeLocationAzureBlobResponse.add_member(:blob_type, Smithy::Schema::Shapes::ShapeRef.new(shape: AzureBlobType, location_name: 'BlobType', traits: {"smithy.api#documentation" => "<p>The type of blob that you want your objects or files to be when transferring them into\n      Azure Blob Storage. Currently, DataSync only supports moving data into Azure Blob\n      Storage as block blobs. For more information on blob types, see the <a href=\"https://learn.microsoft.com/en-us/rest/api/storageservices/understanding-block-blobs--append-blobs--and-page-blobs\">Azure Blob Storage documentation</a>.</p>"}))
    DescribeLocationAzureBlobResponse.add_member(:access_tier, Smithy::Schema::Shapes::ShapeRef.new(shape: AzureAccessTier, location_name: 'AccessTier', traits: {"smithy.api#documentation" => "<p>The access tier that you want your objects or files transferred into. This only applies\n      when using the location as a transfer destination. For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/creating-azure-blob-location.html#azure-blob-access-tiers\">Access tiers</a>.</p>"}))
    DescribeLocationAzureBlobResponse.add_member(:agent_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: AgentArnList, location_name: 'AgentArns', traits: {"smithy.api#documentation" => "<p>The ARNs of the DataSync agents that can connect with your Azure Blob Storage\n      container.</p>"}))
    DescribeLocationAzureBlobResponse.add_member(:creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Time, location_name: 'CreationTime', traits: {"smithy.api#documentation" => "<p>The time that your Azure Blob Storage transfer location was created.</p>"}))
    DescribeLocationAzureBlobResponse.add_member(:managed_secret_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ManagedSecretConfig, location_name: 'ManagedSecretConfig', traits: {"smithy.api#documentation" => "<p>Describes configuration information for a DataSync-managed secret, such as an\n      authentication token that DataSync uses to access a specific storage location.\n        DataSync uses the default Amazon Web Services-managed KMS key to\n      encrypt this secret in Secrets Manager.</p>"}))
    DescribeLocationAzureBlobResponse.add_member(:cmk_secret_config, Smithy::Schema::Shapes::ShapeRef.new(shape: CmkSecretConfig, location_name: 'CmkSecretConfig', traits: {"smithy.api#documentation" => "<p>Describes configuration information for a DataSync-managed secret, such as an\n      authentication token that DataSync uses to access a specific storage location, with\n      a customer-managed KMS key.</p>"}))
