    DescribeTaskExecutionResponse.add_member(:task_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskMode, location_name: 'TaskMode', traits: {"smithy.api#documentation" => "<p>The task mode that you're using. For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/choosing-task-mode.html\">Choosing a task mode for your data\n        transfer</a>.</p>"}))
    DescribeTaskExecutionResponse.add_member(:files_prepared, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'FilesPrepared', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The number of objects that DataSync will attempt to transfer after comparing\n      your source and destination locations.</p>\n         <note>\n            <p>Applies only to <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/choosing-task-mode.html\">Enhanced mode\n        tasks</a>.</p>\n         </note>\n         <p>This counter isn't applicable if you configure your task to <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/configure-metadata.html#task-option-transfer-mode\">transfer\n        all data</a>. In that scenario, DataSync copies everything from the source to\n      the destination without comparing differences between the locations.</p>"}))
    DescribeTaskExecutionResponse.add_member(:files_listed, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskExecutionFilesListedDetail, location_name: 'FilesListed', traits: {"smithy.api#documentation" => "<p>The number of\n      objects\n      that DataSync\n      finds\n      at your locations.</p>\n         <note>\n            <p>Applies only to <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/choosing-task-mode.html\">Enhanced mode\n        tasks</a>.</p>\n         </note>"}))
    DescribeTaskExecutionResponse.add_member(:files_failed, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskExecutionFilesFailedDetail, location_name: 'FilesFailed', traits: {"smithy.api#documentation" => "<p>The number of objects that DataSync fails to prepare, transfer, verify, and\n      delete during your task execution.</p>\n         <note>\n            <p>Applies only to <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/choosing-task-mode.html\">Enhanced mode\n        tasks</a>.</p>\n         </note>"}))
    DescribeTaskExecutionResponse.add_member(:launch_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Time, location_name: 'LaunchTime', traits: {"smithy.api#documentation" => "<p>The time that the task execution actually begins. For non-queued tasks,\n        <code>LaunchTime</code> and <code>StartTime</code> are typically the same. For queued tasks,\n        <code>LaunchTime</code> is typically later than <code>StartTime</code> because previously\n      queued tasks must finish running before newer tasks can begin.</p>"}))
