    PosixPermissions.add_member(:preserve, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PRESERVE', traits: {"smithy.api#enumValue" => "PRESERVE"}))
