    PrivateLinkConfig.add_member(:vpc_endpoint_id, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcEndpointId, location_name: 'VpcEndpointId', traits: {"smithy.api#documentation" => "<p>Specifies the ID of the VPC endpoint that your agent connects to.</p>"}))
    PrivateLinkConfig.add_member(:private_link_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: Endpoint, location_name: 'PrivateLinkEndpoint', traits: {"smithy.api#documentation" => "<p>Specifies the VPC endpoint provided by <a href=\"https://docs.aws.amazon.com/vpc/latest/privatelink/privatelink-share-your-services.html\">Amazon Web Services PrivateLink</a> that your agent connects to.</p>"}))
    PrivateLinkConfig.add_member(:subnet_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: PLSubnetArnList, location_name: 'SubnetArns', traits: {"smithy.api#documentation" => "<p>Specifies the ARN of the subnet where your VPC endpoint is located. You can only specify\n      one ARN.</p>"}))
    PrivateLinkConfig.add_member(:security_group_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: PLSecurityGroupArnList, location_name: 'SecurityGroupArns', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Resource Names (ARN) of the security group that provides DataSync access to your VPC endpoint. You can only specify one ARN.</p>"}))
    PrivateLinkConfig.type = Types::PrivateLinkConfig
    QopConfiguration.add_member(:rpc_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: HdfsRpcProtection, location_name: 'RpcProtection', traits: {"smithy.api#documentation" => "<p>The RPC protection setting configured on the HDFS cluster. This setting corresponds to\n      your <code>hadoop.rpc.protection</code> setting in your <code>core-site.xml</code> file on\n      your Hadoop cluster.</p>"}))
    QopConfiguration.add_member(:data_transfer_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: HdfsDataTransferProtection, location_name: 'DataTransferProtection', traits: {"smithy.api#documentation" => "<p>The data transfer protection setting configured on the HDFS cluster. This setting\n      corresponds to your <code>dfs.data.transfer.protection</code> setting in the\n        <code>hdfs-site.xml</code> file on your Hadoop cluster.</p>"}))
    QopConfiguration.type = Types::QopConfiguration
    ReportDestination.add_member(:s3, Smithy::Schema::Shapes::ShapeRef.new(shape: ReportDestinationS3, location_name: 'S3', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon S3 bucket where DataSync uploads your task\n      report.</p>"}))
    ReportDestination.type = Types::ReportDestination
    ReportDestinationS3.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: S3Subdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>Specifies a bucket prefix for your report.</p>"}))
    ReportDestinationS3.add_member(:s3_bucket_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: S3BucketArn, location_name: 'S3BucketArn', traits: {"smithy.api#documentation" => "<p>Specifies the ARN of the S3 bucket where DataSync uploads your report.</p>", "smithy.api#required" => {}}))
    ReportDestinationS3.add_member(:bucket_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IamRoleArn, location_name: 'BucketAccessRoleArn', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Resource Name (ARN) of the IAM policy that allows\n        DataSync to upload a task report to your S3 bucket. For more information, see\n        <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/task-reports.html\">Allowing\n          DataSync to upload a task report to an Amazon S3 bucket</a>.</p>", "smithy.api#required" => {}}))
    ReportDestinationS3.type = Types::ReportDestinationS3
