    StartTaskExecutionRequest.add_member(:excludes, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterList, location_name: 'Excludes', traits: {"smithy.api#documentation" => "<p>Specifies a list of filter rules that determines which files to exclude from a task. The\n      list contains a single filter string that consists of the patterns to exclude. The patterns\n      are delimited by \"|\" (that is, a pipe), for example, <code>\"/folder1|/folder2\"</code>. </p>"}))
    StartTaskExecutionRequest.add_member(:manifest_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ManifestConfig, location_name: 'ManifestConfig', traits: {"smithy.api#documentation" => "<p>Configures a manifest, which is a list of files or objects that you want DataSync to transfer. For more information and configuration examples, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/transferring-with-manifest.html\">Specifying what DataSync transfers by using a manifest</a>.</p>\n         <p>When using this parameter, your caller identity (the role that you're using DataSync with) must have the <code>iam:PassRole</code> permission. The <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/security-iam-awsmanpol.html#security-iam-awsmanpol-awsdatasyncfullaccess\">AWSDataSyncFullAccess</a> policy includes this permission.</p>\n         <p>To remove a manifest configuration, specify this parameter with an empty value.</p>"}))
    StartTaskExecutionRequest.add_member(:task_report_config, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskReportConfig, location_name: 'TaskReportConfig', traits: {"smithy.api#documentation" => "<p>Specifies how you want to configure a task report, which provides detailed information\n      about your DataSync transfer. For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/task-reports.html\">Monitoring your DataSync\n        transfers with task reports</a>.</p>\n         <p>When using this parameter, your caller identity (the role that you're using DataSync with) must have the <code>iam:PassRole</code> permission. The <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/security-iam-awsmanpol.html#security-iam-awsmanpol-awsdatasyncfullaccess\">AWSDataSyncFullAccess</a> policy includes this permission.</p>\n         <p>To remove a task report configuration, specify this parameter as empty.</p>"}))
    StartTaskExecutionRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: InputTagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Specifies the tags that you want to apply to the Amazon Resource Name (ARN) representing\n      the task execution.</p>\n         <p>\n            <i>Tags</i> are key-value pairs that help you manage, filter, and search for\n      your DataSync resources.</p>"}))
