    UpdateLocationAzureBlobRequest.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: AzureBlobSubdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>Specifies path segments if you want to limit your transfer to a virtual directory in your\n      container (for example, <code>/my/images</code>).</p>"}))
    UpdateLocationAzureBlobRequest.add_member(:authentication_type, Smithy::Schema::Shapes::ShapeRef.new(shape: AzureBlobAuthenticationType, location_name: 'AuthenticationType', traits: {"smithy.api#documentation" => "<p>Specifies the authentication method DataSync uses to access your Azure Blob\n      Storage. DataSync can access blob storage using a shared access signature\n      (SAS).</p>"}))
