    UpdateLocationEfsRequest.add_member(:location_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationArn, location_name: 'LocationArn', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Resource Name (ARN) of the Amazon EFS transfer location that\n      you're updating.</p>", "smithy.api#required" => {}}))
    UpdateLocationEfsRequest.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: EfsSubdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>Specifies a mount path for your Amazon EFS file system. This is where DataSync reads or writes data on your file system (depending on if this is a source or\n      destination location).</p>\n         <p>By default, DataSync uses the root directory (or <a href=\"https://docs.aws.amazon.com/efs/latest/ug/efs-access-points.html\">access point</a> if you provide one by using\n        <code>AccessPointArn</code>). You can also include subdirectories using forward slashes (for\n      example, <code>/path/to/folder</code>).</p>"}))
    UpdateLocationEfsRequest.add_member(:access_point_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: UpdatedEfsAccessPointArn, location_name: 'AccessPointArn', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Resource Name (ARN) of the access point that DataSync uses\n      to mount your Amazon EFS file system.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/create-efs-location.html#create-efs-location-iam\">Accessing\n        restricted Amazon EFS file systems</a>.</p>"}))
    UpdateLocationEfsRequest.add_member(:file_system_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: UpdatedEfsIamRoleArn, location_name: 'FileSystemAccessRoleArn', traits: {"smithy.api#documentation" => "<p>Specifies an Identity and Access Management (IAM) role that allows DataSync to access your Amazon EFS file system.</p>\n         <p>For information on creating this role, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/create-efs-location.html#create-efs-location-iam-role\">Creating a DataSync\n        IAM role for Amazon EFS file system access</a>.</p>"}))
    UpdateLocationEfsRequest.add_member(:in_transit_encryption, Smithy::Schema::Shapes::ShapeRef.new(shape: EfsInTransitEncryption, location_name: 'InTransitEncryption', traits: {"smithy.api#documentation" => "<p>Specifies whether you want DataSync to use Transport Layer Security (TLS) 1.2\n      encryption when it transfers data to or from your Amazon EFS file system.</p>\n         <p>If you specify an access point using <code>AccessPointArn</code> or an IAM\n      role using <code>FileSystemAccessRoleArn</code>, you must set this parameter to\n        <code>TLS1_2</code>.</p>"}))
    UpdateLocationEfsRequest.type = Types::UpdateLocationEfsRequest
    UpdateLocationEfsResponse.type = Types::UpdateLocationEfsResponse
    UpdateLocationFsxLustreRequest.add_member(:location_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationArn, location_name: 'LocationArn', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Resource Name (ARN) of the FSx for Lustre transfer location\n      that you're updating.</p>", "smithy.api#required" => {}}))
    UpdateLocationFsxLustreRequest.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbSubdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>Specifies a mount path for your FSx for Lustre file system. The path can include\n      subdirectories.</p>\n         <p>When the location is used as a source, DataSync reads data from the mount path.\n      When the location is used as a destination, DataSync writes data to the mount path.\n      If you don't include this parameter, DataSync uses the file system's root directory\n        (<code>/</code>).</p>"}))
    UpdateLocationFsxLustreRequest.type = Types::UpdateLocationFsxLustreRequest
    UpdateLocationFsxLustreResponse.type = Types::UpdateLocationFsxLustreResponse
    UpdateLocationFsxOntapRequest.add_member(:location_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationArn, location_name: 'LocationArn', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Resource Name (ARN) of the FSx for ONTAP transfer location\n      that you're updating.</p>", "smithy.api#required" => {}}))
    UpdateLocationFsxOntapRequest.add_member(:protocol, Smithy::Schema::Shapes::ShapeRef.new(shape: FsxUpdateProtocol, location_name: 'Protocol', traits: {"smithy.api#documentation" => "<p>Specifies the data transfer protocol that DataSync uses to access your Amazon FSx file system.</p>"}))
    UpdateLocationFsxOntapRequest.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: FsxOntapSubdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>Specifies a path to the file share in the storage virtual machine (SVM) where you want to\n      transfer data to or from.</p>\n         <p>You can specify a junction path (also known as a mount point), qtree path (for NFS file\n      shares), or share name (for SMB file shares). For example, your mount path might be\n        <code>/vol1</code>, <code>/vol1/tree1</code>, or <code>/share1</code>.</p>\n         <note>\n            <p>Don't specify a junction path in the SVM's root volume. For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/managing-svms.html\">Managing FSx for ONTAP storage virtual machines</a> in the <i>Amazon FSx for NetApp ONTAP User Guide</i>.</p>\n         </note>"}))
    UpdateLocationFsxOntapRequest.type = Types::UpdateLocationFsxOntapRequest
