    UpdateLocationFsxWindowsRequest.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: FsxWindowsSubdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>Specifies a mount path for your file system using forward slashes. DataSync uses\n      this subdirectory to read or write data (depending on whether the file system is a source or\n      destination location).</p>"}))
    UpdateLocationFsxWindowsRequest.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: UpdateSmbDomain, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>Specifies the name of the Windows domain that your FSx for Windows File Server file system\n      belongs to.</p>\n         <p>If you have multiple Active Directory domains in your environment, configuring this\n      parameter makes sure that DataSync connects to the right file system.</p>"}))
    UpdateLocationFsxWindowsRequest.add_member(:user, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbUser, location_name: 'User', traits: {"smithy.api#documentation" => "<p>Specifies the user with the permissions to mount and access the files, folders, and file\n      metadata in your FSx for Windows File Server file system.</p>\n         <p>For information about choosing a user with the right level of access for your transfer,\n      see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/create-fsx-location.html#create-fsx-windows-location-permissions\">required permissions</a> for FSx for Windows File Server locations.</p>"}))
    UpdateLocationFsxWindowsRequest.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbPassword, location_name: 'Password', traits: {"smithy.api#documentation" => "<p>Specifies the password of the user with the permissions to mount and access the files,\n      folders, and file metadata in your FSx for Windows File Server file system.</p>"}))
