    UpdateLocationHdfsRequest.add_member(:location_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationArn, location_name: 'LocationArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the source HDFS cluster location.</p>", "smithy.api#required" => {}}))
    UpdateLocationHdfsRequest.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: HdfsSubdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>A subdirectory in the HDFS cluster. This subdirectory is used to read data from or write\n      data to the HDFS cluster.</p>"}))
    UpdateLocationHdfsRequest.add_member(:name_nodes, Smithy::Schema::Shapes::ShapeRef.new(shape: HdfsNameNodeList, location_name: 'NameNodes', traits: {"smithy.api#documentation" => "<p>The NameNode that manages the HDFS namespace. The NameNode performs operations such as\n      opening, closing, and renaming files and directories. The NameNode contains the information to\n      map blocks of data to the DataNodes. You can use only one NameNode.</p>"}))
    UpdateLocationHdfsRequest.add_member(:block_size, Smithy::Schema::Shapes::ShapeRef.new(shape: HdfsBlockSize, location_name: 'BlockSize', traits: {"smithy.api#documentation" => "<p>The size of the data blocks to write into the HDFS cluster. </p>"}))
    UpdateLocationHdfsRequest.add_member(:replication_factor, Smithy::Schema::Shapes::ShapeRef.new(shape: HdfsReplicationFactor, location_name: 'ReplicationFactor', traits: {"smithy.api#documentation" => "<p>The number of DataNodes to replicate the data to when writing to the HDFS cluster. </p>"}))
    UpdateLocationHdfsRequest.add_member(:kms_key_provider_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: KmsKeyProviderUri, location_name: 'KmsKeyProviderUri', traits: {"smithy.api#documentation" => "<p>The URI of the HDFS cluster's Key Management Server (KMS). </p>"}))
    UpdateLocationHdfsRequest.add_member(:qop_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: QopConfiguration, location_name: 'QopConfiguration', traits: {"smithy.api#documentation" => "<p>The Quality of Protection (QOP) configuration specifies the Remote Procedure Call (RPC)\n      and data transfer privacy settings configured on the Hadoop Distributed File System (HDFS)\n      cluster. </p>"}))
    UpdateLocationHdfsRequest.add_member(:authentication_type, Smithy::Schema::Shapes::ShapeRef.new(shape: HdfsAuthenticationType, location_name: 'AuthenticationType', traits: {"smithy.api#documentation" => "<p>The type of authentication used to determine the identity of the user. </p>"}))
    UpdateLocationHdfsRequest.add_member(:simple_user, Smithy::Schema::Shapes::ShapeRef.new(shape: HdfsUser, location_name: 'SimpleUser', traits: {"smithy.api#documentation" => "<p>The user name used to identify the client on the host operating system.</p>"}))
    UpdateLocationHdfsRequest.add_member(:kerberos_principal, Smithy::Schema::Shapes::ShapeRef.new(shape: KerberosPrincipal, location_name: 'KerberosPrincipal', traits: {"smithy.api#documentation" => "<p>The Kerberos principal with access to the files and folders on the HDFS cluster. </p>"}))
    UpdateLocationHdfsRequest.add_member(:kerberos_keytab, Smithy::Schema::Shapes::ShapeRef.new(shape: KerberosKeytabFile, location_name: 'KerberosKeytab', traits: {"smithy.api#documentation" => "<p>The Kerberos key table (keytab) that contains mappings between the defined Kerberos\n      principal and the encrypted keys. You can load the keytab from a file by providing the file's\n      address.</p>"}))
    UpdateLocationHdfsRequest.add_member(:kerberos_krb5_conf, Smithy::Schema::Shapes::ShapeRef.new(shape: KerberosKrb5ConfFile, location_name: 'KerberosKrb5Conf', traits: {"smithy.api#documentation" => "<p>The <code>krb5.conf</code> file that contains the Kerberos configuration information. You\n      can load the <code>krb5.conf</code> file by providing the file's address. If you're using the\n        CLI, it performs the base64 encoding for you. Otherwise, provide the\n      base64-encoded text.</p>"}))
    UpdateLocationHdfsRequest.add_member(:agent_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: AgentArnList, location_name: 'AgentArns', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Names (ARNs) of the DataSync agents that can connect to your\n      HDFS cluster.</p>"}))
