    UpdateLocationObjectStorageRequest.add_member(:location_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationArn, location_name: 'LocationArn', traits: {"smithy.api#documentation" => "<p>Specifies the ARN of the object storage system location that you're updating.</p>", "smithy.api#required" => {}}))
    UpdateLocationObjectStorageRequest.add_member(:server_port, Smithy::Schema::Shapes::ShapeRef.new(shape: ObjectStorageServerPort, location_name: 'ServerPort', traits: {"smithy.api#documentation" => "<p>Specifies the port that your object storage server accepts inbound network traffic on (for\n      example, port 443).</p>"}))
    UpdateLocationObjectStorageRequest.add_member(:server_protocol, Smithy::Schema::Shapes::ShapeRef.new(shape: ObjectStorageServerProtocol, location_name: 'ServerProtocol', traits: {"smithy.api#documentation" => "<p>Specifies the protocol that your object storage server uses to communicate.</p>"}))
    UpdateLocationObjectStorageRequest.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: S3Subdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>Specifies the object prefix for your object storage server. If this is a source location,\n      DataSync only copies objects with this prefix. If this is a destination location, DataSync\n      writes all objects with this prefix.</p>"}))
    UpdateLocationObjectStorageRequest.add_member(:server_hostname, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerHostname, location_name: 'ServerHostname', traits: {"smithy.api#documentation" => "<p>Specifies the domain name or IP address (IPv4 or IPv6) of the object storage server that\n      your DataSync agent connects to.</p>"}))
    UpdateLocationObjectStorageRequest.add_member(:access_key, Smithy::Schema::Shapes::ShapeRef.new(shape: ObjectStorageAccessKey, location_name: 'AccessKey', traits: {"smithy.api#documentation" => "<p>Specifies the access key (for example, a user name) if credentials are required to\n      authenticate with the object storage server.</p>"}))
    UpdateLocationObjectStorageRequest.add_member(:secret_key, Smithy::Schema::Shapes::ShapeRef.new(shape: ObjectStorageSecretKey, location_name: 'SecretKey', traits: {"smithy.api#documentation" => "<p>Specifies the secret key (for example, a password) if credentials are required to\n      authenticate with the object storage server.</p>\n         <note>\n            <p>If you provide a secret using <code>SecretKey</code>, but do not provide secret\n        configuration details using <code>CmkSecretConfig</code> or <code>CustomSecretConfig</code>,\n        then DataSync stores the token using your Amazon Web Services account's Secrets Manager secret.</p>\n         </note>"}))
    UpdateLocationObjectStorageRequest.add_member(:agent_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: AgentArnList, location_name: 'AgentArns', traits: {"smithy.api#documentation" => "<p>(Optional) Specifies the Amazon Resource Names (ARNs) of the DataSync agents\n      that can connect with your object storage system. If you are setting up an agentless\n      cross-cloud transfer, you do not need to specify a value for this parameter.</p>\n         <note>\n            <p>You cannot add or remove agents from a storage location after you initially create\n        it.</p>\n         </note>"}))
    UpdateLocationObjectStorageRequest.add_member(:server_certificate, Smithy::Schema::Shapes::ShapeRef.new(shape: ObjectStorageCertificate, location_name: 'ServerCertificate', traits: {"smithy.api#documentation" => "<p>Specifies a certificate chain for DataSync to authenticate with your object\n      storage system if the system uses a private or self-signed certificate authority (CA). You\n      must specify a single <code>.pem</code> file with a full certificate chain (for example,\n        <code>file:///home/user/.ssh/object_storage_certificates.pem</code>).</p>\n         <p>The certificate chain might include:</p>\n         <ul>\n            <li>\n               <p>The object storage system's certificate</p>\n            </li>\n            <li>\n               <p>All intermediate certificates (if there are any)</p>\n            </li>\n            <li>\n               <p>The root certificate of the signing CA</p>\n            </li>\n         </ul>\n         <p>You can concatenate your certificates into a <code>.pem</code> file (which can be up to\n      32768 bytes before base64 encoding). The following example <code>cat</code> command creates an\n        <code>object_storage_certificates.pem</code> file that includes three certificates:</p>\n         <p>\n            <code>cat object_server_certificate.pem intermediate_certificate.pem\n        ca_root_certificate.pem > object_storage_certificates.pem</code>\n         </p>\n         <p>To use this parameter, configure <code>ServerProtocol</code> to <code>HTTPS</code>.</p>\n         <p>Updating this parameter doesn't interfere with tasks that you have in progress.</p>"}))
    UpdateLocationObjectStorageRequest.add_member(:cmk_secret_config, Smithy::Schema::Shapes::ShapeRef.new(shape: CmkSecretConfig, location_name: 'CmkSecretConfig', traits: {"smithy.api#documentation" => "<p>Specifies configuration information for a DataSync-managed secret, such as an\n      authentication token or set of credentials that DataSync uses to access a specific\n      transfer location, and a customer-managed KMS key.</p>"}))
    UpdateLocationObjectStorageRequest.add_member(:custom_secret_config, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomSecretConfig, location_name: 'CustomSecretConfig', traits: {"smithy.api#documentation" => "<p>Specifies configuration information for a customer-managed secret, such as an\n      authentication token or set of credentials that DataSync uses to access a specific\n      transfer location, and a customer-managed KMS key.</p>"}))
    UpdateLocationObjectStorageRequest.type = Types::UpdateLocationObjectStorageRequest
    UpdateLocationObjectStorageResponse.type = Types::UpdateLocationObjectStorageResponse
    UpdateLocationS3Request.add_member(:location_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationArn, location_name: 'LocationArn', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Resource Name (ARN) of the Amazon S3 transfer location that\n      you're updating.</p>", "smithy.api#required" => {}}))
    UpdateLocationS3Request.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: S3Subdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>Specifies a prefix in the S3 bucket that DataSync reads from or writes to\n      (depending on whether the bucket is a source or destination location).</p>\n         <note>\n            <p>DataSync can't transfer objects with a prefix that begins with a slash (<code>/</code>)\n        or includes <code>//</code>, <code>/./</code>, or <code>/../</code> patterns. For\n        example:</p>\n            <ul>\n               <li>\n                  <p>\n                     <code>/photos</code>\n                  </p>\n               </li>\n               <li>\n                  <p>\n                     <code>photos//2006/January</code>\n                  </p>\n               </li>\n               <li>\n                  <p>\n                     <code>photos/./2006/February</code>\n                  </p>\n               </li>\n               <li>\n                  <p>\n                     <code>photos/../2006/March</code>\n                  </p>\n               </li>\n            </ul>\n         </note>"}))
    UpdateLocationS3Request.add_member(:s3_storage_class, Smithy::Schema::Shapes::ShapeRef.new(shape: S3StorageClass, location_name: 'S3StorageClass', traits: {"smithy.api#documentation" => "<p>Specifies the storage class that you want your objects to use when Amazon S3 is a\n      transfer destination.</p>\n         <p>For buckets in Amazon Web Services Regions, the storage class defaults to\n        <code>STANDARD</code>. For buckets on Outposts, the storage class defaults to\n        <code>OUTPOSTS</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/create-s3-location.html#using-storage-classes\">Storage class\n        considerations with Amazon S3 transfers</a>.</p>"}))
    UpdateLocationS3Request.add_member(:s3_config, Smithy::Schema::Shapes::ShapeRef.new(shape: S3Config, location_name: 'S3Config'))
    UpdateLocationS3Request.type = Types::UpdateLocationS3Request
    UpdateLocationS3Response.type = Types::UpdateLocationS3Response
    UpdateLocationSmbRequest.add_member(:location_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationArn, location_name: 'LocationArn', traits: {"smithy.api#documentation" => "<p>Specifies the ARN of the SMB location that you want to update.</p>", "smithy.api#required" => {}}))
    UpdateLocationSmbRequest.add_member(:subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbSubdirectory, location_name: 'Subdirectory', traits: {"smithy.api#documentation" => "<p>Specifies the name of the share exported by your SMB file server where DataSync\n      will read or write data. You can include a subdirectory in the share path (for example,\n        <code>/path/to/subdirectory</code>). Make sure that other SMB clients in your network can\n      also mount this path.</p>\n         <p>To copy all data in the specified subdirectory, DataSync must be able to mount\n      the SMB share and access all of its data. For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/create-smb-location.html#configuring-smb-permissions\">Providing DataSync access to SMB file servers</a>.</p>"}))
    UpdateLocationSmbRequest.add_member(:server_hostname, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerHostname, location_name: 'ServerHostname', traits: {"smithy.api#documentation" => "<p>Specifies the domain name or IP address (IPv4 or IPv6) of the SMB file server that your DataSync agent connects to.</p>\n         <note>\n            <p>If you're using Kerberos authentication, you must specify a domain name.</p>\n         </note>"}))
    UpdateLocationSmbRequest.add_member(:user, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbUser, location_name: 'User', traits: {"smithy.api#documentation" => "<p>Specifies the user name that can mount your SMB file server and has permission to access\n      the files and folders involved in your transfer. This parameter applies only if\n        <code>AuthenticationType</code> is set to <code>NTLM</code>.</p>\n         <p>For information about choosing a user with the right level of access for your transfer,\n      see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/create-smb-location.html#configuring-smb-permissions\">Providing DataSync access to SMB file servers</a>.</p>"}))
    UpdateLocationSmbRequest.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbDomain, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>Specifies the Windows domain name that your SMB file server belongs to. This parameter\n      applies only if <code>AuthenticationType</code> is set to <code>NTLM</code>.</p>\n         <p>If you have multiple domains in your environment, configuring this parameter makes sure\n      that DataSync connects to the right file server.</p>"}))
    UpdateLocationSmbRequest.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbPassword, location_name: 'Password', traits: {"smithy.api#documentation" => "<p>Specifies the password of the user who can mount your SMB file server and has permission\n      to access the files and folders involved in your transfer. This parameter applies only if\n        <code>AuthenticationType</code> is set to <code>NTLM</code>.</p>"}))
    UpdateLocationSmbRequest.add_member(:agent_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: AgentArnList, location_name: 'AgentArns', traits: {"smithy.api#documentation" => "<p>Specifies the DataSync agent (or agents) that can connect to your SMB file\n      server. You specify an agent by using its Amazon Resource Name (ARN).</p>"}))
    UpdateLocationSmbRequest.add_member(:mount_options, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbMountOptions, location_name: 'MountOptions'))
    UpdateLocationSmbRequest.add_member(:authentication_type, Smithy::Schema::Shapes::ShapeRef.new(shape: SmbAuthenticationType, location_name: 'AuthenticationType', traits: {"smithy.api#documentation" => "<p>Specifies the authentication protocol that DataSync uses to connect to your SMB\n      file server. DataSync supports <code>NTLM</code> (default) and <code>KERBEROS</code>\n      authentication.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/create-smb-location.html#configuring-smb-permissions\">Providing DataSync access to SMB file servers</a>.</p>"}))
    UpdateLocationSmbRequest.add_member(:dns_ip_addresses, Smithy::Schema::Shapes::ShapeRef.new(shape: DnsIpList, location_name: 'DnsIpAddresses', traits: {"smithy.api#documentation" => "<p>Specifies the IP addresses (IPv4 or IPv6) for the DNS servers that your SMB file server belongs to.\n      This parameter applies only if <code>AuthenticationType</code> is set to\n      <code>KERBEROS</code>.</p>\n         <p>If you have multiple domains in your environment, configuring this parameter makes sure\n      that DataSync connects to the right SMB file server. </p>"}))
    UpdateLocationSmbRequest.add_member(:kerberos_principal, Smithy::Schema::Shapes::ShapeRef.new(shape: KerberosPrincipal, location_name: 'KerberosPrincipal', traits: {"smithy.api#documentation" => "<p>Specifies a Kerberos prinicpal, which is an identity in your Kerberos realm that has\n      permission to access the files, folders, and file metadata in your SMB file server.</p>\n         <p>A Kerberos principal might look like <code>HOST/kerberosuser@MYDOMAIN.ORG</code>.</p>\n         <p>Principal names are case sensitive. Your DataSync task execution will fail if\n      the principal that you specify for this parameter doesn’t exactly match the principal that you\n      use to create the keytab file.</p>"}))
    UpdateLocationSmbRequest.add_member(:kerberos_keytab, Smithy::Schema::Shapes::ShapeRef.new(shape: KerberosKeytabFile, location_name: 'KerberosKeytab', traits: {"smithy.api#documentation" => "<p>Specifies your Kerberos key table (keytab) file, which includes mappings between your\n      Kerberos principal and encryption keys.</p>\n         <p>To avoid task execution errors, make sure that the Kerberos principal that you use to\n      create the keytab file matches exactly what you specify for\n      <code>KerberosPrincipal</code>.</p>"}))
    UpdateLocationSmbRequest.add_member(:kerberos_krb5_conf, Smithy::Schema::Shapes::ShapeRef.new(shape: KerberosKrb5ConfFile, location_name: 'KerberosKrb5Conf', traits: {"smithy.api#documentation" => "<p>Specifies a Kerberos configuration file (<code>krb5.conf</code>) that defines your\n      Kerberos realm configuration.</p>\n         <p>The file must be base64 encoded. If you're using the CLI, the encoding is\n      done for you.</p>"}))
    UpdateLocationSmbRequest.type = Types::UpdateLocationSmbRequest
    UpdateLocationSmbResponse.type = Types::UpdateLocationSmbResponse
    UpdateTaskExecutionRequest.add_member(:task_execution_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskExecutionArn, location_name: 'TaskExecutionArn', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Resource Name (ARN) of the task execution that you're\n      updating.</p>", "smithy.api#required" => {}}))
    UpdateTaskExecutionRequest.add_member(:options, Smithy::Schema::Shapes::ShapeRef.new(shape: Options, location_name: 'Options', traits: {"smithy.api#required" => {}}))
