    UpdateTaskRequest.add_member(:task_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskArn, location_name: 'TaskArn', traits: {"smithy.api#documentation" => "<p>Specifies the ARN of the task that you want to update.</p>", "smithy.api#required" => {}}))
    UpdateTaskRequest.add_member(:options, Smithy::Schema::Shapes::ShapeRef.new(shape: Options, location_name: 'Options'))
    UpdateTaskRequest.add_member(:excludes, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterList, location_name: 'Excludes', traits: {"smithy.api#documentation" => "<p>Specifies exclude filters that define the files, objects, and folders in your source\n      location that you don't want DataSync to transfer. For more information and\n      examples, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/filtering.html\">Specifying what DataSync transfers by using filters</a>.</p>"}))
    UpdateTaskRequest.add_member(:schedule, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskSchedule, location_name: 'Schedule', traits: {"smithy.api#documentation" => "<p>Specifies a schedule for when you want your task to run. For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/task-scheduling.html\">Scheduling your\n        task</a>.</p>"}))
    UpdateTaskRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: TagValue, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>Specifies the name of your task.</p>"}))
    UpdateTaskRequest.add_member(:cloud_watch_log_group_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LogGroupArn, location_name: 'CloudWatchLogGroupArn', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Resource Name (ARN) of an Amazon CloudWatch log group for\n      monitoring your task.</p>\n         <p>For Enhanced mode tasks, you must use <code>/aws/datasync</code> as your log group\n      name. For example:</p>\n         <p>\n            <code>arn:aws:logs:us-east-1:111222333444:log-group:/aws/datasync:*</code>\n         </p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/configure-logging.html\">Monitoring data transfers with\n          CloudWatch Logs</a>.</p>"}))
    UpdateTaskRequest.add_member(:includes, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterList, location_name: 'Includes', traits: {"smithy.api#documentation" => "<p>Specifies include filters define the files, objects, and folders in your source location\n      that you want DataSync to transfer. For more information and examples, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/filtering.html\">Specifying what DataSync transfers by using filters</a>.</p>"}))
    UpdateTaskRequest.add_member(:manifest_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ManifestConfig, location_name: 'ManifestConfig', traits: {"smithy.api#documentation" => "<p>Configures a manifest, which is a list of files or objects that you want DataSync to transfer. For more information and configuration examples, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/transferring-with-manifest.html\">Specifying what DataSync transfers by using a manifest</a>.</p>\n         <p>When using this parameter, your caller identity (the IAM role that you're\n      using DataSync with) must have the <code>iam:PassRole</code> permission. The <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/security-iam-awsmanpol.html#security-iam-awsmanpol-awsdatasyncfullaccess\">AWSDataSyncFullAccess</a> policy includes this permission.</p>\n         <p>To remove a manifest configuration, specify this parameter as empty.</p>"}))
    UpdateTaskRequest.add_member(:task_report_config, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskReportConfig, location_name: 'TaskReportConfig', traits: {"smithy.api#documentation" => "<p>Specifies how you want to configure a task report, which provides detailed information\n      about your DataSync transfer. For more information, see <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/task-reports.html\">Monitoring your DataSync\n        transfers with task reports</a>.</p>\n         <p>When using this parameter, your caller identity (the IAM role that you're\n      using DataSync with) must have the <code>iam:PassRole</code> permission. The <a href=\"https://docs.aws.amazon.com/datasync/latest/userguide/security-iam-awsmanpol.html#security-iam-awsmanpol-awsdatasyncfullaccess\">AWSDataSyncFullAccess</a> policy includes this permission.</p>\n         <p>To remove a task report configuration, specify this parameter as empty.</p>"}))
